import React, { useEffect, useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'react-toastify';
import { useAuth } from '../AuthContext';

const Stars = ({ rating, interactive, onSelect }) => (
  <div className="stars" style={{ cursor: interactive ? 'pointer' : 'default' }}>
    {[1,2,3,4,5].map(i => (
      <span key={i} className={`star ${i <= Math.round(rating) ? 'filled' : ''}`}
        style={{ fontSize: interactive ? 24 : 14 }}
        onClick={() => interactive && onSelect && onSelect(i)}>★</span>
    ))}
  </div>
);

export default function CourseDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [course, setCourse] = useState(null);
  const [enrolled, setEnrolled] = useState(false);
  const [loading, setLoading] = useState(true);
  const [enrollLoading, setEnrollLoading] = useState(false);
  const [activeModule, setActiveModule] = useState(null);
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewComment, setReviewComment] = useState('');
  const [submittingReview, setSubmittingReview] = useState(false);

  useEffect(() => {
    const load = async () => {
      try {
        const { data } = await axios.get(`/api/courses/${id}`);
        setCourse(data);
        if (data.modules?.length) setActiveModule(data.modules[0]._id);
        if (user) {
          const check = await axios.get(`/api/enrollments/check/${id}`);
          setEnrolled(check.data.enrolled);
        }
      } catch { navigate('/courses'); }
      setLoading(false);
    };
    load();
  }, [id, user]);

  const handleEnroll = async () => {
    if (!user) return navigate('/login');
    setEnrollLoading(true);
    try {
      await axios.post(`/api/enrollments/${id}`);
      setEnrolled(true);
      toast.success('🎉 Enrolled successfully!');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Enrollment failed');
    }
    setEnrollLoading(false);
  };

  const submitReview = async () => {
    if (!user) return navigate('/login');
    setSubmittingReview(true);
    try {
      const { data } = await axios.post(`/api/courses/${id}/reviews`, { rating: reviewRating, comment: reviewComment });
      setCourse(data);
      setReviewComment('');
      toast.success('✅ Review submitted!');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Review failed');
    }
    setSubmittingReview(false);
  };

  if (loading) return (
    <div style={{ minHeight: '100vh', paddingTop: 80, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="loader" />
    </div>
  );
  if (!course) return null;

  const totalLessons = course.modules?.reduce((a, m) => a + m.lessons.length, 0) || 0;

  return (
    <div style={{ minHeight: '100vh', paddingTop: 80 }}>
      {/* Hero */}
      <div style={{ background: 'linear-gradient(180deg, rgba(124,58,237,0.18) 0%, transparent 100%)', padding: '56px 0 48px', borderBottom: '1px solid rgba(124,58,237,0.1)' }}>
        <div className="page-container">
          <div style={{ display: 'grid', gridTemplateColumns: '1fr minmax(300px, 360px)', gap: 48, alignItems: 'start' }}>
            {/* Left */}
            <div>
              <div style={{ display: 'flex', gap: 8, marginBottom: 16, flexWrap: 'wrap' }}>
                <span className="badge badge-purple">{course.category}</span>
                <span className={`badge ${course.level === 'beginner' ? 'badge-neon' : course.level === 'advanced' ? 'badge-pink' : 'badge-purple'}`}>{course.level}</span>
                {course.isPublished && <span className="badge badge-gold">✓ Published</span>}
              </div>
              <h1 style={{ fontSize: 'clamp(26px, 3.5vw, 40px)', fontWeight: 900, lineHeight: 1.2, marginBottom: 16 }}>{course.title}</h1>
              <p style={{ fontSize: 17, color: '#b8b0d8', lineHeight: 1.7, marginBottom: 24 }}>{course.shortDescription || course.description}</p>
              <div style={{ display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap', marginBottom: 24 }}>
                <Stars rating={course.averageRating} />
                <span style={{ fontWeight: 800, color: '#ffd700' }}>{course.averageRating?.toFixed(1) || '0.0'}</span>
                <span style={{ color: '#6b6490' }}>({course.reviews?.length || 0} reviews)</span>
                <span style={{ color: '#6b6490' }}>👥 {course.totalStudents} students</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{ width: 44, height: 44, borderRadius: '50%', background: 'linear-gradient(135deg, #7c3aed, #00f5d4)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, fontSize: 18, color: 'white' }}>
                  {course.instructor?.name?.charAt(0)}
                </div>
                <div>
                  <div style={{ fontSize: 14, color: '#6b6490' }}>Created by</div>
                  <div style={{ fontWeight: 700, color: '#c084fc' }}>{course.instructor?.name}</div>
                </div>
              </div>
            </div>

            {/* Enrollment Card */}
            <div className="glass" style={{ padding: 28, borderRadius: 20, position: 'sticky', top: 90 }}>
              <div style={{ height: 180, borderRadius: 12, marginBottom: 20, overflow: 'hidden', background: 'linear-gradient(135deg, #0e0b1e, #14112a)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 80 }}>
                {course.thumbnail ? <img src={`http://localhost:5000/${course.thumbnail}`} style={{ width: '100%', height: '100%', objectFit: 'cover' }} alt="" /> : '🎓'}
              </div>
              <div style={{ fontSize: 36, fontWeight: 900, marginBottom: 20, color: course.price === 0 ? '#00f5d4' : '#c084fc' }}>
                {course.price === 0 ? 'Free' : `$${course.price}`}
              </div>
              {enrolled ? (
                <Link to={`/learn/${id}`} className="btn btn-primary" style={{ width: '100%', justifyContent: 'center', fontSize: 16, padding: '14px 0' }}>
                  🎬 Continue Learning
                </Link>
              ) : (
                <button className="btn btn-primary" style={{ width: '100%', justifyContent: 'center', fontSize: 16, padding: '14px 0' }}
                  onClick={handleEnroll} disabled={enrollLoading}>
                  {enrollLoading ? 'Enrolling...' : '🚀 Enroll Now'}
                </button>
              )}
              <div style={{ marginTop: 20, display: 'flex', flexDirection: 'column', gap: 10 }}>
                {[
                  ['📚', `${course.modules?.length || 0} Modules`],
                  ['🎬', `${totalLessons} Lessons`],
                  ['📶', course.level],
                  ['🌐', course.language || 'English'],
                  ['🏆', 'Certificate of completion'],
                ].map(([icon, text]) => (
                  <div key={text} style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 14, color: '#b8b0d8' }}>
                    <span>{icon}</span><span>{text}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="page-container" style={{ padding: '48px 24px' }}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr minmax(300px, 360px)', gap: 48 }}>
          <div>
            {/* What You'll Learn */}
            {course.whatYouLearn?.length > 0 && (
              <div className="glass" style={{ padding: 28, borderRadius: 16, marginBottom: 32 }}>
                <h2 style={{ fontSize: 22, fontWeight: 800, marginBottom: 20, color: '#f0eeff' }}>What You'll Learn</h2>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                  {course.whatYouLearn.map((item, i) => (
                    <div key={i} style={{ display: 'flex', gap: 10, fontSize: 14, color: '#b8b0d8', alignItems: 'flex-start' }}>
                      <span style={{ color: '#00f5d4', marginTop: 2, flexShrink: 0 }}>✓</span>{item}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Curriculum */}
            <div style={{ marginBottom: 32 }}>
              <h2 style={{ fontSize: 22, fontWeight: 800, marginBottom: 20, color: '#f0eeff' }}>Course Curriculum</h2>
              {course.modules?.map((mod, mi) => (
                <div key={mod._id} className="glass" style={{ marginBottom: 12, borderRadius: 14, overflow: 'hidden' }}>
                  <button onClick={() => setActiveModule(activeModule === mod._id ? null : mod._id)} style={{
                    width: '100%', padding: '16px 20px', background: 'none', border: 'none',
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between', cursor: 'pointer',
                    color: '#f0eeff', fontWeight: 700, fontSize: 16,
                    borderBottom: activeModule === mod._id ? '1px solid rgba(124,58,237,0.2)' : 'none'
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                      <div style={{ width: 28, height: 28, borderRadius: 8, background: 'linear-gradient(135deg, #7c3aed, #a855f7)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 800, color: 'white' }}>{mi + 1}</div>
                      {mod.title}
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <span style={{ fontSize: 12, color: '#6b6490' }}>{mod.lessons.length} lessons</span>
                      <span style={{ color: '#7c3aed', transition: 'transform 0.3s', transform: activeModule === mod._id ? 'rotate(180deg)' : 'none' }}>▼</span>
                    </div>
                  </button>
                  {activeModule === mod._id && (
                    <div>
                      {mod.lessons.map((lesson, li) => (
                        <div key={lesson._id} style={{ padding: '12px 20px 12px 32px', display: 'flex', alignItems: 'center', gap: 12, borderBottom: li < mod.lessons.length - 1 ? '1px solid rgba(124,58,237,0.08)' : 'none' }}>
                          <span style={{ fontSize: 16 }}>{lesson.videoUrl ? '🎬' : '📄'}</span>
                          <span style={{ fontSize: 14, color: '#b8b0d8', flex: 1 }}>{lesson.title}</span>
                          {lesson.isFree && <span className="badge badge-neon" style={{ fontSize: 10 }}>Free</span>}
                          {lesson.duration > 0 && <span style={{ fontSize: 12, color: '#6b6490' }}>{Math.round(lesson.duration / 60)} min</span>}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>

            {/* Reviews */}
            <div>
              <h2 style={{ fontSize: 22, fontWeight: 800, marginBottom: 24, color: '#f0eeff' }}>
                Student Reviews <span style={{ fontSize: 16, color: '#6b6490', fontWeight: 400 }}>({course.reviews?.length})</span>
              </h2>

              {user && !course.reviews?.find(r => r.user?._id === user.id) && (
                <div className="glass" style={{ padding: 24, borderRadius: 16, marginBottom: 24 }}>
                  <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 16, color: '#f0eeff' }}>Leave a Review</h3>
                  <div style={{ marginBottom: 14 }}>
                    <Stars rating={reviewRating} interactive onSelect={setReviewRating} />
                  </div>
                  <textarea className="input" rows={3} placeholder="Share your experience..."
                    value={reviewComment} onChange={e => setReviewComment(e.target.value)}
                    style={{ resize: 'vertical', marginBottom: 14 }} />
                  <button className="btn btn-primary btn-sm" onClick={submitReview} disabled={submittingReview}>
                    {submittingReview ? 'Submitting...' : '✓ Submit Review'}
                  </button>
                </div>
              )}

              <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                {course.reviews?.map(review => (
                  <div key={review._id} className="glass" style={{ padding: '20px 24px', borderRadius: 14 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 10 }}>
                      <div style={{ width: 36, height: 36, borderRadius: '50%', background: 'linear-gradient(135deg, #7c3aed, #f72585)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, fontSize: 14, color: 'white' }}>
                        {review.user?.name?.charAt(0) || 'U'}
                      </div>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 14, color: '#f0eeff' }}>{review.user?.name || 'Anonymous'}</div>
                        <Stars rating={review.rating} />
                      </div>
                      <div style={{ marginLeft: 'auto', fontSize: 12, color: '#6b6490' }}>
                        {new Date(review.createdAt).toLocaleDateString()}
                      </div>
                    </div>
                    {review.comment && <p style={{ fontSize: 14, color: '#b8b0d8', lineHeight: 1.6 }}>{review.comment}</p>}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Sidebar - About Instructor */}
          <div>
            <div className="glass" style={{ padding: 28, borderRadius: 16 }}>
              <h3 style={{ fontSize: 18, fontWeight: 800, marginBottom: 20, color: '#f0eeff' }}>Your Instructor</h3>
              <div style={{ display: 'flex', gap: 14, marginBottom: 16 }}>
                <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'linear-gradient(135deg, #7c3aed, #00f5d4)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, fontWeight: 900, color: 'white', flexShrink: 0 }}>
                  {course.instructor?.name?.charAt(0)}
                </div>
                <div>
                  <div style={{ fontWeight: 800, fontSize: 16, color: '#c084fc' }}>{course.instructor?.name}</div>
                  <div style={{ fontSize: 13, color: '#6b6490' }}>{course.instructor?.createdCourses?.length || 0} courses</div>
                </div>
              </div>
              {course.instructor?.bio && <p style={{ fontSize: 14, color: '#b8b0d8', lineHeight: 1.6 }}>{course.instructor.bio}</p>}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
